    internal static class ModernVisual
    {
        private static string folder;
        private static int count;
        private static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;File.AppendAllText(Path.Combine(folder,"checks.txt"),"PASS "+label+Environment.NewLine);}
        private static async Task AssistantMotionPreview()
        {
            var scene=new Grid{Width=320,Height=220,Background=Design.Brush("#101015")};var visual=new AssistantVisual{Width=150,Height=150,VerticalAlignment=VerticalAlignment.Center};scene.Children.Add(visual);var label=Design.Text("MacFlow · Asistente",15,true);label.Foreground=Brushes.White;label.HorizontalAlignment=HorizontalAlignment.Center;label.VerticalAlignment=VerticalAlignment.Bottom;label.Margin=new Thickness(0,0,0,15);scene.Children.Add(label);
            var view=Design.Panel("Vista previa · Movimiento del asistente",320,220);view.ShowActivated=false;view.Content=scene;view.Show();visual.Set(AssistantStage.Working);
            try{var frames=Path.Combine(folder,"assistant-motion");Directory.CreateDirectory(frames);for(int i=0;i<40;i++){await Task.Delay(40);var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(320,220,96,96,PixelFormats.Pbgra32);bitmap.Render(scene);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(frames,i.ToString("D2")+".png")))encoder.Save(file);}visual.Set(AssistantStage.Ready);Check(!visual.Rendering,"el asistente detiene su renderizador al volver a reposo; la vista previa no usa voz ni micrófono");}finally{visual.Dispose();WindowLife.Close(view);}
        }
        private static async Task CheckCapsuleMotion()
        {
            double at60=126,v60=0,at120=126,v120=0,peak=126;
            for(int i=0;i<60;i++){IslandMotion.Step(ref at60,ref v60,388,1.0/60);peak=Math.Max(peak,at60);}
            for(int i=0;i<120;i++)IslandMotion.Step(ref at120,ref v120,388,1.0/120);
            Check(Math.Abs(at60-at120)<.000001&&Math.Abs(at60-388)<.01&&peak>388&&peak<394,"isla mantiene duración a 60/120 Hz con rebote menor al 2% del recorrido");
            double value=126,velocity=0;IslandMotion.Step(ref value,ref velocity,388,.05);double before=value;IslandMotion.Step(ref value,ref velocity,126,.0001);
            Check(Math.Abs(value-before)<1&&velocity>0,"invertir la isla conserva velocidad y continuidad sin saltar al inicio");
            var fixture=Design.Panel("Isla · fixture de resorte",126,30);fixture.Left=200;fixture.Top=100;fixture.ShowActivated=false;var shell=new Border{Background=Brushes.Black};fixture.Content=shell;fixture.Show();
            var motion=new IslandMotion(fixture,shell,delegate{});
            try{motion.To(388,204,130);await Task.Delay(55);motion.To(126,30,100);await Task.Delay(55);motion.To(388,204,130);await Task.Delay(1050);File.AppendAllText(Path.Combine(folder,"checks.txt"),"INFO resorte activo="+motion.Running+" ancho="+fixture.Width+" alto="+fixture.Height+" top="+fixture.Top+Environment.NewLine);Check(!motion.Running&&fixture.Width==388&&fixture.Height==204&&Math.Abs(fixture.Top-130)<=1,"abrir cerrar y reabrir la isla termina exactamente y retira el renderizador");motion.To(126,30);bool animations=Design.Animations;try{Design.Animations=false;await Task.Delay(90);Check(!motion.Running&&fixture.Width==126&&fixture.Height==30,"activar movimiento reducido durante expansión detiene y completa el resorte");}finally{Design.Animations=animations;}}
            finally{motion.Dispose();WindowLife.Close(fixture);}
        }
        private static async Task CheckTransitions()
        {
            var fixture=Design.Panel("Fixture de transición reversible",300,200);fixture.SetValue(PanelMotion.UseDockEntrance,true);fixture.ShowActivated=false;fixture.Content=Design.Glass(Design.Text("Una sola transición por ventana",16,true),24,false);fixture.Left=240;fixture.Top=140;fixture.Show();int transitions=0;
            Action<Window,GenieSurface> started=delegate(Window source,GenieSurface surface){if(source==fixture)transitions++;};GenieTransition.Started+=started;
            try{Design.Reveal(fixture);await Task.Delay(65);Design.Dismiss(fixture);await Task.Delay(35);Check(transitions==1&&GenieTransition.ActiveCount<=1,"abrir y cerrar retargetea un único efecto sin copiar el Dock");await Task.Delay(550);Check(!WindowLife.Alive(fixture)&&GenieTransition.ActiveCount==0,"la transición libera el HWND y su caché");}finally{GenieTransition.Started-=started;WindowLife.Close(fixture);}
        }
        private static async Task CheckControlLevels(Desktop desktop)
        {
            string saved=desktop.Preferences.ControlCenterLayout;
            try{foreach(string layout in new[]{"Mac","iPad"}){desktop.Preferences.ControlCenterLayout=layout;var backend=new ControlFixture();var control=new ControlCenter(desktop,backend);control.ShowActivated=false;control.Show();try{await Task.Delay(300);var slider=control.VolumeSlider;slider.ApplyTemplate();var track=(System.Windows.Controls.Primitives.Track)slider.Template.FindName("PART_Track",slider);bool vertical=slider.Orientation==Orientation.Vertical;Check(track!=null&&(vertical?track.ValueFromPoint(new Point(32,30))>track.ValueFromPoint(new Point(32,120)):track.ValueFromPoint(new Point(slider.ActualWidth*.75,10))>track.ValueFromPoint(new Point(slider.ActualWidth*.25,10))),"regulador conserva dirección y pista interactiva · "+layout);slider.Value=73;await Task.Delay(120);Check(backend.VolumeWrites>0&&Math.Abs(backend.State.Volume-73)<.1,"regulador envía volumen al proveedor sin escritura por cuadro · "+layout);}finally{WindowLife.Close(control);}}}finally{desktop.Preferences.ControlCenterLayout=saved;}
        }
        private static async Task CheckDockSlide()
        {
            var dock=Design.Panel("Dock · fixture estable",240,70);dock.Left=200;dock.Top=400;dock.ShowActivated=false;dock.Content=Design.Text("Dock de prueba",14,false);dock.Show();var visibility=new DockVisibility(dock);Native.RECT original;Native.GetWindowRect(new WindowInteropHelper(dock).Handle,out original);
            try{visibility.Hide();await Task.Delay(85);var resting=visibility.RestingBounds();Check(Math.Abs(resting.Top-original.Top)<=1,"zona del cursor permanece fija mientras el Dock baja");visibility.Show();for(int i=0;i<15;i++){await Task.Delay(25);visibility.Show();}Native.RECT end;Native.GetWindowRect(new WindowInteropHelper(dock).Handle,out end);Check(Math.Abs(end.Top-original.Top)<=1,"mostrar repetidamente no reinicia rebotes ni desplaza el Dock");visibility.Hide();await Task.Delay(70);visibility.PositionChanging();Check(!dock.IsVisible,"reubicar durante ocultación no resucita un Dock marcado oculto");}finally{WindowLife.Close(dock);}
        }
